-- Bestaande gemeentelijke regelingen (dubbelingen uit scan 2026-10-17): alleen lege velden aanvullen; status/bedragen ongemoeid.
-- Plus: werkgebied 'Landelijk' bij regelingen van de vier gemeente-financiers corrigeren naar de gemeente zelf.
with v(funder_id,bestaand,beschr,link) as (values
('da444543-fd37-440b-b36e-f04059425add'::uuid,'Jaarlijkse subsidie Cultuurplan 2025-2028','Instellingen die in het meerjarige Cultuurplan zijn opgenomen dienen hier jaarlijks hun aanvraag en jaarstukken in voor het komende subsidiejaar. De voorwaarden worden per instelling via een persoonlijke e-mail gecommuniceerd. Nieuwe instellingen kunnen hier niet instromen.','https://www.rotterdam.nl/jaarlijkse-subsidie-cultuurplan-2025-2028-aanvragen/start-jaarlijkse-subsidie-cultuurplan-2025-2028-aanvragen'),
('da444543-fd37-440b-b36e-f04059425add'::uuid,'Projectsubsidie cultuur','Subsidie voor één afgebakend kunst- of cultuurproject in Rotterdam, aan te vragen door zowel individuele makers als organisaties. Na afloop kan voor een volgend project opnieuw worden aangevraagd. Instellingen met een vaste gemeentelijke of rijkssubsidie zijn uitgesloten.','https://www.rotterdam.nl/projectsubsidie-cultuur-aanvragen/start-projectsubsidie-cultuur-aanvragen'),
('da444543-fd37-440b-b36e-f04059425add'::uuid,'Subsidie Cultuurcoach','Subsidie voor het inzetten van cultuurcoaches (kunstvakdocenten of kunstprofessionals) op Rotterdamse scholen of instellingen. Per aanvraag maximaal vijf voltijdse medewerkers. Gebaseerd op de Brede regeling combinatiefuncties – cultuur.','https://www.rotterdam.nl/subsidie-cultuurcoach-aanvragen'),
('5cf9882d-e1ba-42a4-a886-1295814c49fa'::uuid,'Subsidie Haagse kunst- en cultuurprojecten','Bijdrage voor publieksgerichte, professionele projecten in muziek, theater, dans, film, literatuur, beeldende kunst of combinaties daarvan, met een looptijd van maximaal een jaar. Kleinere aanvragen (categorie A) beoordeelt de gemeente zelf, grotere (categorie B) gaan langs een adviescommissie. Gemeentelijk aandeel in de begroting is begrensd (70% resp. 30%).','https://mijnsubsidie.denhaag.nl/regeling/6abb6a8d69bcf80ae85f347e'),
('5cf9882d-e1ba-42a4-a886-1295814c49fa'::uuid,'Subsidieregeling makers','Persoonlijke subsidie waarmee een professionele maker een eigen ontwikkelplan kan uitvoeren, bijvoorbeeld via experiment, cursussen, coaching of workshops. Presentaties zoals exposities vallen erbuiten. Bij samenwerking met een culturele organisatie of minimaal drie zzp''ers ligt het maximum hoger (€9.000 i.p.v. €4.500).','https://mijnsubsidie.denhaag.nl/regeling/69df5ec2060f860b71898f75'),
('5cf9882d-e1ba-42a4-a886-1295814c49fa'::uuid,'Subsidieregeling Muurschilderingen Den Haag','Bijdrage voor het laten maken van een muurschildering in de buurt door een professionele kunstenaar. Het initiatief moet van een bewoner komen en twee derde van de directe buren moet instemmen.','https://www.denhaag.nl/wp-content/uploads/2025/06/251015_OCW_Formulieren_Subsidieregeling_Muurschilderingen_CN_v2t.pdf'),
('5cf9882d-e1ba-42a4-a886-1295814c49fa'::uuid,'Subsidie inclusief samenleven','Subsidie voor activiteiten die mensen verbinden en discriminatie tegengaan, voor vrouwen- en queeremancipatie en aanpak van straatintimidatie, en voor projecten over de geschiedenis van kolonialisme en slavernij. Er zijn project-, jaar- en tweejarige subsidies, met lagere maxima voor individuele aanvragers.','https://mijnsubsidie.denhaag.nl/'),
('5cf9882d-e1ba-42a4-a886-1295814c49fa'::uuid,'Subsidie Samen sociaal en vitaal','Subsidie voor activiteiten die ouderen, mantelzorgers en andere kwetsbare inwoners sterker, gezonder en minder eenzaam maken. Naast meerjarige subsidies voor kleine en grote activiteiten (nu gesloten) is er een onderdeel voor vernieuwende projecten en vrijwilligersorganisaties tot €15.000.','https://www.denhaag.nl/nl/subsidies/subsidie-samen-sociaal-en-vitaal-aanvragen/'),
('5cf9882d-e1ba-42a4-a886-1295814c49fa'::uuid,'Subsidieregeling sociale initiatieven in de wijk','Subsidie voor sociale, culturele of sportieve activiteiten die buurtbewoners samenbrengen, de buurt prettiger maken of jongeren veilig laten opgroeien. Elk stadsdeel heeft een eigen budget en eigen maximum (van €20.000 in Leidschenveen-Ypenburg tot €60.000 in Centrum).','https://www.denhaag.nl/wp-content/uploads/2024/05/240364_DPZ_Aanvraagformulier_Sociale_Initiatieven_SH_v4t.pdf'),
('8c323256-dce8-41c3-b9c7-031c1ed089cb'::uuid,'Amateurkunst','Bijdrage voor amateurkunstgroepen in de kosten van artistieke leiding, repetitieruimte en huur van materialen. De groep komt minstens 12 keer per jaar samen en presenteert zich minimaal eenmaal per jaar openbaar in Utrecht. Maximaal 50% van de kosten.','https://loket.digitaal.utrecht.nl/nl/producten/amateurkunst-subsidie-aanvragen'),
('8c323256-dce8-41c3-b9c7-031c1ed089cb'::uuid,'Culturele broedplaats/maakplek','Investeringssubsidie voor het realiseren of uitbreiden van culturele broedplaatsen in Utrecht, zoals verwervings-, (ver)bouw- en advieskosten. De ruimtes worden tegen betaalbaar tarief verhuurd aan kleinschalige makers en organisaties in kunst en cultuur.','https://mijnsubsidie.utrecht.nl/regeling/65674582adaa02ec94accac7'),
('8c323256-dce8-41c3-b9c7-031c1ed089cb'::uuid,'Vrijwillige inzet voor elkaar (onderdeel C)','Subsidie voor vrijwillige inzet voor anderen, onder meer informele zorg, steun aan mantelzorgers, armoede- en schuldeninitiatieven en welzijnsaccommodaties in zelfbeheer. Gericht op inwoners in een kwetsbare situatie en mensen die taal- of digitale vaardigheden willen verbeteren.','https://mijnsubsidie.utrecht.nl/regeling/5f3d0226c083b745449f92cd'),
('8c323256-dce8-41c3-b9c7-031c1ed089cb'::uuid,'Cultuur in de vrije tijd','Kleine bijdrage voor groepen inwoners die samen in hun vrije tijd aan cultuur doen, voor artistieke begeleiding, ruimtehuur of materialen.','https://mijnsubsidie.utrecht.nl/regeling/6a46066cece4b9104f61e16e'),
('8c323256-dce8-41c3-b9c7-031c1ed089cb'::uuid,'Impulssubsidie cultuur','Kleine subsidie voor startende culturele projecten in alle disciplines die artistiek kunnen groeien of het stedelijke aanbod verrijken, met een presentatiemoment voor Utrechters.','https://loket.digitaal.utrecht.nl/nl/producten/impulssubsidie-cultuur-aanvragen'),
('8c323256-dce8-41c3-b9c7-031c1ed089cb'::uuid,'Projectsubsidie cultuur','Subsidie voor bijzondere of vernieuwende culturele projecten in alle kunstvormen met een presentatie in Utrecht, zowel professioneel als amateur, educatief of participatief.','https://mijnsubsidie.utrecht.nl/regeling/5df376bbbc85275d22318410')
)
update public.subsidieregelingen s set
  algemene_beschrijving = coalesce(s.algemene_beschrijving, v.beschr),
  aanvraaglink = coalesce(s.aanvraaglink, v.link),
  updated_at = now()
from v where s.funder_id=v.funder_id and lower(s.naam)=lower(v.bestaand)
  and (s.algemene_beschrijving is null or s.aanvraaglink is null);

update public.subsidieregelingen s set werkgebied = g.naam, updated_at = now()
from (values ('ad8c41cd-b5d1-4de3-99fa-7bc9c2d61d7b'::uuid,'Amsterdam'),('da444543-fd37-440b-b36e-f04059425add'::uuid,'Rotterdam'),('5cf9882d-e1ba-42a4-a886-1295814c49fa'::uuid,'Den Haag'),('8c323256-dce8-41c3-b9c7-031c1ed089cb'::uuid,'Utrecht')) g(funder_id,naam)
where s.funder_id=g.funder_id and s.werkgebied='Landelijk';
